import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Statistic, Alert, Badge, Button, Table, Tag, Space, Typography, Divider } from 'antd';
import { 
  SafetyOutlined,
  WarningOutlined, 
  ExclamationCircleOutlined,
  FireOutlined,
  ReloadOutlined,
  SettingOutlined 
} from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { apiRequest } from '../api';

const { Title, Text } = Typography;

interface SecurityStatus {
  current_level: string;
  is_emergency_stopped: boolean;
  last_check: string;
  active_anomalies: number;
  active_events: number;
}

interface SecurityEvent {
  id: string;
  title: string;
  alert_level: string;
  event_time: string;
}

interface DashboardData {
  system_status: SecurityStatus;
  event_statistics: any;
  ethics_statistics: any;
  active_events: SecurityEvent[];
  last_updated: string;
}

const SecurityDashboard: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [dashboardData, setDashboardData] = useState<DashboardData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await apiRequest('/api/security/dashboard', 'GET');
      setDashboardData(response);
    } catch (err: any) {
      setError(err.message || 'Ошибка загрузки данных');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDashboardData();
    // Автообновление каждые 30 секунд
    const interval = setInterval(fetchDashboardData, 30000);
    return () => clearInterval(interval);
  }, []);

  const getSecurityLevelColor = (level: string) => {
    switch (level.toLowerCase()) {
      case 'normal': return 'success';
      case 'elevated': return 'warning';
      case 'high': return 'error';
      case 'critical': return 'error';
      case 'emergency': return 'error';
      default: return 'default';
    }
  };

  const getAlertLevelColor = (level: string) => {
    switch (level.toLowerCase()) {
      case 'info': return 'blue';
      case 'warning': return 'orange';
      case 'critical': return 'red';
      case 'emergency': return 'red';
      default: return 'default';
    }
  };

  const eventColumns = [
    {
      title: 'Время',
      dataIndex: 'event_time',
      key: 'event_time',
      render: (time: string) => new Date(time).toLocaleString('ru-RU'),
      width: 150,
    },
    {
      title: 'Событие',
      dataIndex: 'title',
      key: 'title',
    },
    {
      title: 'Уровень',
      dataIndex: 'alert_level',
      key: 'alert_level',
      render: (level: string) => (
        <Tag color={getAlertLevelColor(level)}>
          {level.toUpperCase()}
        </Tag>
      ),
      width: 100,
    },
  ];

  if (loading && !dashboardData) {
    return (
      <div style={{ padding: '24px', textAlign: 'center' }}>
        <ReloadOutlined spin style={{ fontSize: '24px' }} />
        <div style={{ marginTop: '16px' }}>Загрузка данных безопасности...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ padding: '24px' }}>
        <Alert
          message="Ошибка загрузки"
          description={error}
          type="error"
          showIcon
          action={
            <Button size="small" onClick={fetchDashboardData}>
              Повторить
            </Button>
          }
        />
      </div>
    );
  }

  if (!dashboardData) {
    return (
      <div style={{ padding: '24px' }}>
        <Alert message="Нет данных" type="info" />
      </div>
    );
  }

  const { system_status, event_statistics, ethics_statistics, active_events } = dashboardData;

  return (
    <div style={{ padding: '24px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
        <Title level={2}>
          <SafetyOutlined style={{ marginRight: '8px' }} />
          Панель безопасности
        </Title>
        <Space>
          <Button 
            icon={<SettingOutlined />} 
            onClick={() => navigate('/security/settings')}
          >
            Настройки
          </Button>
          <Button 
            icon={<ReloadOutlined />} 
            onClick={fetchDashboardData}
            loading={loading}
          >
            Обновить
          </Button>
        </Space>
      </div>

      {/* Статус системы */}
      {system_status.is_emergency_stopped && (
        <Alert
          message="СИСТЕМА В РЕЖИМЕ АВАРИЙНОЙ ОСТАНОВКИ"
          description="Все операции Soul заблокированы. Требуется ручное восстановление."
          type="error"
          showIcon
          icon={<FireOutlined />}
          style={{ marginBottom: '24px' }}
          action={
            <Button danger onClick={() => navigate('/security/emergency')}>
              Управление
            </Button>
          }
        />
      )}

      {/* Основные метрики */}
      <Row gutter={[16, 16]} style={{ marginBottom: '24px' }}>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="Уровень безопасности"
              value={system_status.current_level}
              valueStyle={{ 
                color: getSecurityLevelColor(system_status.current_level) === 'success' ? '#3f8600' : 
                       getSecurityLevelColor(system_status.current_level) === 'warning' ? '#cf1322' : '#cf1322'
              }}
              prefix={<SafetyOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="Активные аномалии"
              value={system_status.active_anomalies}
              valueStyle={{ color: system_status.active_anomalies > 0 ? '#cf1322' : '#3f8600' }}
              prefix={<WarningOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="Активные события"
              value={system_status.active_events}
              valueStyle={{ color: system_status.active_events > 0 ? '#cf1322' : '#3f8600' }}
              prefix={<ExclamationCircleOutlined />}
            />
          </Card>
        </Col>
        <Col xs={24} sm={12} lg={6}>
          <Card>
            <Statistic
              title="Последняя проверка"
              value={new Date(system_status.last_check).toLocaleTimeString('ru-RU')}
              prefix={<ReloadOutlined />}
            />
          </Card>
        </Col>
      </Row>

      {/* Статистика */}
      <Row gutter={[16, 16]} style={{ marginBottom: '24px' }}>
        <Col xs={24} lg={12}>
          <Card title="Статистика событий" size="small">
            <Row gutter={16}>
              <Col span={12}>
                <Statistic
                  title="Всего событий"
                  value={event_statistics?.total_events || 0}
                  size="small"
                />
              </Col>
              <Col span={12}>
                <Statistic
                  title="Критических"
                  value={event_statistics?.critical_events || 0}
                  valueStyle={{ color: '#cf1322' }}
                  size="small"
                />
              </Col>
            </Row>
          </Card>
        </Col>
        <Col xs={24} lg={12}>
          <Card title="Этические проверки" size="small">
            <Row gutter={16}>
              <Col span={12}>
                <Statistic
                  title="Всего проверок"
                  value={ethics_statistics?.total_checks || 0}
                  size="small"
                />
              </Col>
              <Col span={12}>
                <Statistic
                  title="Нарушений"
                  value={ethics_statistics?.violations || 0}
                  valueStyle={{ color: '#cf1322' }}
                  size="small"
                />
              </Col>
            </Row>
          </Card>
        </Col>
      </Row>

      {/* Активные события */}
      <Card 
        title="Активные события безопасности" 
        size="small"
        extra={
          <Button 
            size="small" 
            onClick={() => navigate('/security/events')}
          >
            Все события
          </Button>
        }
      >
        {active_events.length > 0 ? (
          <Table
            dataSource={active_events}
            columns={eventColumns}
            rowKey="id"
            pagination={false}
            size="small"
          />
        ) : (
          <div style={{ textAlign: 'center', padding: '20px', color: '#666' }}>
            Активных событий нет
          </div>
        )}
      </Card>

      {/* Быстрые действия */}
      <Divider />
      <div style={{ textAlign: 'center' }}>
        <Space wrap>
          <Button onClick={() => navigate('/security/anomalies')}>
            Аномалии
          </Button>
          <Button onClick={() => navigate('/security/events')}>
            События
          </Button>
          <Button onClick={() => navigate('/security/ethics')}>
            Этика
          </Button>
          <Button onClick={() => navigate('/security/settings')}>
            Настройки
          </Button>
        </Space>
      </div>

      <div style={{ marginTop: '16px', textAlign: 'center', color: '#666', fontSize: '12px' }}>
        Последнее обновление: {new Date(dashboardData.last_updated).toLocaleString('ru-RU')}
      </div>
    </div>
  );
};

export default SecurityDashboard;